const EVENTS = Array.from({ length: 40 }, (_, index) => {
  const minute = String(59 - index).padStart(2, "0");
  const kinds = [
    "Service Control Manager · 7036",
    "Microsoft-Windows-Kernel-Power · 41",
    "Glass UX Agent · 1002",
    "Group Policy · 1502",
  ];
  return { time: `10:${minute}:12`, source: kinds[index % kinds.length] ?? "" };
});

function EventLog() {
  return (
    <div className="flex flex-col">
      {EVENTS.map((event) => (
        <div key={event.time} className="flex min-w-0 gap-4 py-1.5 type-body">
          <time className="type-mono text-fg-muted">{event.time}</time>
          <span className="min-w-0 truncate">{event.source}</span>
        </div>
      ))}
    </div>
  );
}

