function GuardDemo() {
  const [open, setOpen] = useState(false);
  const [dirty, setDirty] = useState(false);
  const [version, setVersion] = useState(0);
  const guard = useDialogGuard({
    open,
    onOpenChange: (next) => {
      setOpen(next);
      if (!next) setDirty(false);
    },
    dirty,
    onDiscard: () => setVersion((value) => value + 1),
    title: "Discard changes to NST-C106?",
  });
  return (
    <Dialog.Root {...guard.rootProps}>
      <Dialog.Trigger render={<Button>Unsaved changes</Button>} />
      <Dialog.Popup size="md">
        <Dialog.Header icon={<IconEndpoint />} title="Edit device" subtitle="NST-C106" />
        <Dialog.Body>
          <EditDeviceFields key={version} onChange={() => setDirty(true)} />
        </Dialog.Body>
        <Dialog.Footer>
          <Dialog.Close render={<Button>Cancel</Button>} />
          <ActionButton
            variant="primary"
            disabled={!dirty}
            onAction={async () => {
              await wait(700);
              setDirty(false);
            }}
            pendingLabel="Saving…"
            successLabel="Saved"
          >
            Save changes
          </ActionButton>
        </Dialog.Footer>
        {guard.confirm}
      </Dialog.Popup>
    </Dialog.Root>
  );
}

